select sd.D_Name as ipvDName, pro.P_Name as pName, pro.P_Code as pCode, pro.P_Name_History as pNameHistory, pro.P_Inv_Total as pInvTotal, pro.P_Competent_Department as pCompetentDepartment, con.Con_Name as conName, proc.C_Name as pConstructionUnitName, proc.C_Abbreviation as pConsAbbName, prod.D_Name as pCompetentDepartmentName, f.file_relation_id as fileRelationId, yea.Py_Investment_Amount as pyInvestmentAmount, cany.c_name as ipvCName, mn.* from Inv_Plan_Year_Yw mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join Con_Contract con on con.Con_Id = mn.Con_Id left join SYS_Company proc on proc.C_Id = pro.P_Construction_Unit left join SYS_Department prod on prod.D_Id = pro.P_Competent_Department left join SYS_Department sd on mn.Ipv_D_Id = sd.D_ID left join Sys_File f on f.FileID = mn.Ipv_Id left join project_preset_year yea on yea.P_Id = mn.P_Id and yea.Py_Eclare_Year = mn.Ipv_Declare_Year left join SYS_Company cany on mn.Ipv_C_id = cany.c_Id
mn.Ipv_State = 7
and mn.P_Id = #{pId}
and mn.Ipv_Declare_Year = #{year}

        select
        
        sd.D_Name as ipvDName, con.Con_Name as conName,
        yea.Py_Investment_Amount as pyInvestmentAmount,cany.c_name as ipvCName,
        mn.*,yw.ipv_Annual_Pay as ipvAnnualPay
        from Inv_Plan_Year mn
        
